package com.example.ui.components

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

/**
 * Official Phosphor Icons for Jetpack Compose - BOLD weight only.
 *
 * Every path below is the verbatim `d` attribute of the corresponding
 * `assets/bold/<name>-bold.svg` file in the official Phosphor source repository
 * (https://github.com/phosphor-icons/core, MIT licensed). Nothing here is drawn,
 * traced or approximated by hand.
 *
 * Phosphor ships each glyph as a single pre-outlined *filled* path on a 256x256
 * viewport, so these are rendered with `fill` (not `stroke`). The fill colour is a
 * placeholder: `Icon(imageVector = ..., tint = ...)` recolours it through a
 * ColorFilter, which is how every call site in this app already consumes them.
 *
 * Naming: the Kotlin property is the app-facing semantic name; the KDoc and the
 * `icon(...)` argument record the exact official Phosphor asset backing it.
 * Where Phosphor provides a `-simple` variant it is always preferred over the base
 * glyph. Where it does not, the closest existing official icon is used - a
 * `-simple` name is never invented.
 *
 * To add an icon: copy the `d` attribute from `assets/bold/<name>-bold.svg` upstream.
 * Do not hand-author path data.
 */
object PhosphorIcons {
    object Bold {
        private fun icon(phosphorName: String, pathData: String): ImageVector =
            ImageVector.Builder(
                name = "phosphor-bold-$phosphorName",
                defaultWidth = 24.dp,
                defaultHeight = 24.dp,
                viewportWidth = 256f,
                viewportHeight = 256f,
            ).addPath(
                pathData = addPathNodes(pathData),
                fill = SolidColor(Color.Black),
            ).build()

